    """
    # यदि number एक संख्या नहीं है, तो एक त्रुटि संदेश लौटाएँ
    if not isinstance(number, (int, float)):
        raise TypeError("इनपुट एक संख्या होना चाहिए।")

    # यदि number एक दशमलव संख्या है, तो उसे एक पूर्णांक में परिवर्तित करें
    if isinstance(number, float):
        number = int(number)

    # यदि number 0 से कम है, तो एक त्रुटि संदेश लौटाएँ
    if number < 0:
        raise ValueError("नकारात्मक संख्याओं का factorial गणना नहीं की जा सकती है।")

    # यदि method "recursive" या "iterative" नहीं है, तो एक त्रुटि संदेश लौटाएँ
    if method not in ["recursive", "iterative"]:
        raise ValueError("method 'recursive' या 'iterative' होना चाहिए।")

    @functools.lru_cache(maxsize=None)
    def recursive_factorial(n):
        if n == 0 or n == 1:
            return 1
        else:
            return n * recursive_factorial(n-1)

    @functools.lru_cache(maxsize=None)
    def iterative_factorial(n):
        result = 1
        for i in range(1, n + 1):
            result *= i
        return result

    if method == "recursive":
        return recursive_factorial(number)
    else:
        return iterative_factorial(number)

